-- public.best_water_near(p_world uuid, p_uid uuid, p_range integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.best_water_near(p_world uuid, p_uid uuid, p_range integer DEFAULT 3)
 RETURNS TABLE(x integer, y integer, depth double precision)
 LANGUAGE sql
 STABLE
AS $function$
  select gx, gy, water_depth(p_world, gx, gy)
  from player py,
       generate_series(floor(py.x)::int - p_range, floor(py.x)::int + p_range) gx,
       generate_series(floor(py.y)::int - p_range, floor(py.y)::int + p_range) gy
  where py.world_id = p_world and py.uid = p_uid
    and gx >= 0 and gy >= 0 and water_depth(p_world, gx, gy) >= 1
  order by water_depth(p_world, gx, gy) desc limit 1
$function$
